/**
 * Ambient declarations for the virtual modules generated by the Nitro module.
 * They have no on-disk counterpart, so TypeScript needs this contract.
 */
declare module "#facilis/config" {
  const config: import("@facilis.dev/core").FacilisConfig;
  export default config;
  /** Absolute project root, used by runtime code that must read project files. */
  export const projectRoot: string;
  /** Absolute path to the project facilis.config.ts. */
  export const configPath: string;
  /** Raw config source captured when the module was created (revision fallback). */
  export const configSource: string;
  /** Set when facilis.config.ts is missing or unreadable. */
  export const configError: string | undefined;
  /** Framework versions reported in FacilisManifest.framework. */
  export const coreVersion: string;
  export const nitroVersion: string;
}

declare module "#facilis/db-schema" {
  const schema: Readonly<Record<string, unknown>>;
  export default schema;
}

/** Every module under db/views/ plus db/views.ts, for the framework's view creation. */
declare module "#facilis/db-views" {
  const modules: ReadonlyArray<Readonly<Record<string, unknown>>>;
  export default modules;
}

/**
 * Every definition module under server/jobs/ (one default export per file), for the job
 * registry: nested directories are allowed, tests are skipped (D-107, docs/JOBS.md §5).
 */
declare module "#facilis/jobs" {
  const modules: ReadonlyArray<import("./runtime/jobs/contracts.ts").JobModule>;
  export default modules;
}

/**
 * Every definition module under server/workflows/ (one default export per file), for the
 * workflow registry: nested directories are allowed, tests are skipped (D-135).
 */
declare module "#facilis/workflows" {
  const modules: ReadonlyArray<import("./runtime/workflows/contracts.ts").WorkflowModule>;
  export default modules;
}

declare module "#facilis/openapi-meta" {
  const metadata: import("./types.ts").RouteMetadataMap;
  export default metadata;
}
